<?php

declare(strict_types=1);

namespace App\Text\Api;

use App\Api\Contracts\Domains\ApiSender;
use App\Data\Pages\TextSections;
use App\Data\Pages\TextVersionSummary;
use App\Support\TextPart;

/**
 * The API of Text, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class TextApi
{
    public function __construct(private ApiSender $sender) {}

    public function listTextSections(
        string $target,
        string $version,
        int $afterSection = 0,
        int|null $perPage = null,
    ): TextSections {
        return $this->sender->send(ListTextSectionsPayload::from([
            'target' => $target,
            'version' => $version,
            'afterSection' => $afterSection,
            'perPage' => $perPage,
        ]));
    }

    public function readText(
        string $target,
        string $version,
        string|null $section = null,
        int|null $firstLine = null,
        int|null $lastLine = null,
    ): TextPart {
        return $this->sender->send(ReadTextPayload::from([
            'target' => $target,
            'version' => $version,
            'section' => $section,
            'firstLine' => $firstLine,
            'lastLine' => $lastLine,
        ]));
    }

    public function readTextVersion(
        string $target,
        string|null $version = null,
    ): TextVersionSummary {
        return $this->sender->send(ReadTextVersionPayload::from(['target' => $target, 'version' => $version]));
    }
}
